ee:variables.ee:set-variable:
%dw 2.0
output text/plain
var meta = read(payload, "application/xml")
// Pick the HIGHEST published version (semver) from the versions list, NOT <release>.
// On Anypoint Exchange the <release>/<latest> tags can lag behind the newest custom-asset
// upload, which silently serves an OLDER matrix (e.g. one missing the connectors block or
// with a munit rule lacking dependency coordinates) → connector pinning is quietly skipped.
var vers = (meta.metadata.versioning.versions.*version default []) map ((v) -> (v as String))
fun vnum(v) = do {
    var p = (v splitBy ".") map ((s) -> ((s as Number) default 0))
    --- ((p[0] default 0) * 1000000) + ((p[1] default 0) * 1000) + (p[2] default 0)
}
---
if (!isEmpty(vers)) ((vers orderBy vnum($))[-1] as String)
else ((meta.metadata.versioning.latest default meta.metadata.versioning.release) as String)

%dw 2.0
output text/plain
var meta = read(payload, "application/xml")
// Pick the HIGHEST published version (semver), NOT <release> — Exchange's <release>/<latest>
// tags can lag behind the newest custom-asset upload, silently serving an older registry.
var vers = (meta.metadata.versioning.versions.*version default []) map ((v) -> (v as String))
fun vnum(v) = do {
    var p = (v splitBy ".") map ((s) -> ((s as Number) default 0))
    --- ((p[0] default 0) * 1000000) + ((p[1] default 0) * 1000) + (p[2] default 0)
}
---
if (!isEmpty(vers)) ((vers orderBy vnum($))[-1] as String)
else ((meta.metadata.versioning.latest default meta.metadata.versioning.release) as String)

%dw 2.0
output application/java

// ── Tier-1: registry entry (null when app is not registered) ──────────────
var regEntry = vars.registry.apps[vars.appName]

// ── Tier-2: request body overrides — set by the entry-point flow before any sub-flow call.
// Default to empty object so field access (req.owner etc.) is null rather than a runtime error.
var req = vars.requestBody default {}

// ── owner ─────────────────────────────────────────────────────────────────
//   Tier 3 convention: always p('github.defaultOwner') — unconditional property
var resolvedOwner =
    (regEntry.owner     default null)
    default (req.owner  default null)
    default p('github.defaultOwner')

// ── repo ──────────────────────────────────────────────────────────────────
//   Tier 3 convention: repo = appName when naming.repoEqualsAppName == 'true'
var conventionRepo =
    if (p('naming.repoEqualsAppName') == 'true') vars.appName
    else null

var resolvedRepo =
    (regEntry.repo     default null)
    default (req.repo  default null)
    default conventionRepo

// ── appPath ───────────────────────────────────────────────────────────────
//   Tier 3 convention: appPath = '.' when naming.appPathAtRoot == 'true'
var conventionAppPath =
    if (p('naming.appPathAtRoot') == 'true') '.'
    else null

var resolvedAppPath =
    (regEntry.appPath     default null)
    default (req.appPath  default null)
    default conventionAppPath

// ── orgId ─────────────────────────────────────────────────────────────────
//   Tier 3 convention: always p('anypoint.defaultOrgId')
var resolvedOrgId =
    (regEntry.orgId     default null)
    default (req.orgId  default null)
    default p('anypoint.defaultOrgId')

// ── defaultBranch ─────────────────────────────────────────────────────────
//   Precedence — USER INPUT FIRST (initiation semantics: the caller chooses the
//   branch to change for THIS run; it is not a webhook-driven correlation):
//     1. req.branch          — explicit user-supplied branch (REST/MCP request field)
//     2. req.defaultBranch   — legacy alias for the same intent
//     3. registry entry      — governed per-app default
//   If none of the above resolves a value this stays null; the block AFTER this
//   transform then discovers the repository's real default_branch from the GitHub
//   Repo API (cached), and only falls back to p('github.defaultBranch') on failure.
var resolvedBranch =
    (req.branch                default null)
    default (req.defaultBranch default null)
    default (regEntry.defaultBranch default null)
---
{
    owner:         resolvedOwner,
    repo:          resolvedRepo,
    appPath:       resolvedAppPath,
    orgId:         resolvedOrgId,
    defaultBranch: resolvedBranch
}
